const raw = $json || {};
const body = raw.body || {};
const q = String(body.question || '').trim();
const f = body.step_fields && typeof body.step_fields === 'object' ? body.step_fields : {};
const parts = [];
parts.push('Stap 4 advies (Governance-inrichting).');
if (f.problem) parts.push('Probleem: ' + String(f.problem));
if (f.perspectives) parts.push('Ontbrekend perspectief: ' + String(f.perspectives));
if (f.references) parts.push('Bronnen: ' + String(f.references));
if (q) parts.push('Vraag: ' + q);
parts.push('Werk sturing, toezicht, beheersing en verantwoording uit met KPIs en escalatieregels.');
parts.push('Neem kwaliteitspoorten op voor menselijke validatie.');
return [{ json: { answer: parts.join(' ') } }];
